      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Commander had served as deputy commander at SOCCENT and recognized intrinsic differences between the SOCCENT and SOCNORTH AORs.",
      "spans": [
        "src:883af9d52e37#p127.2"
      ]
    },
    {
      "id": "F3",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The inquiry examined SOCNORTH’s role as a TSOC in light of constraints placed on it by the U.S. Constitution.",
      "spans": [
        "src:883af9d52e37#p127.2"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "assessed",
      "fact": "SOCNORTH operates in a multifaceted environment alongside partners, including FBI, DOE, and DHS, whose activities involve different rules.",
      "spans": [
        "src:883af9d52e37#p127.2"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "assessed",
      "fact": "SOCNORTH is not always the lead organization and may have a significant supporting role.",
      "spans": [
        "src:883af9d52e37#p127.2"
      ]
    },
    {
      "id": "F6",
      "kind": "capability",
      "status": "assessed",
      "fact": "The envisioned future is for SOCNORTH to defend the Homeland in depth through a framework for cooperative action with DOD, interagency, and international partners.",
      "spans": [
        "src:883af9d52e37#p127.3"
      ]
    },
    {
      "id": "F7",
      "kind": "situation",
      "status": "assessed",
      "fact": "The envisioned role is to complement international and interagency partners, support DOD efforts, and lead DOD efforts when appropriate in the NORTHCOM AOR.",
