      ]
    },
    {
      "id": "F8",
      "kind": "capability",
      "status": "assessed",
      "fact": "The proposed approach calls for broadening SOCNORTH’s aperture, expanding and refining its capabilities, and building its network.",
      "spans": [
        "src:883af9d52e37#p127.3"
      ]
    }
  ],
  "options": {
